DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "est2-papers-2026-09-26:l2may:q32", "old_status": "needs_source_repair", "status": "ready", "question_id": "ec415335-137b-5aa1-9159-f0f2621a503f", "stem": "A nonvertical line passes through \\((a^2,3a)\\) and \\((b^2,3b)\\), with a≠b. Which expression gives its y-intercept?", "choices": [{"key": "A", "text": "\\(3ab/(a+b)\\)"}, {"key": "B", "text": "\\(ab/(a+b)\\)"}, {"key": "C", "text": "\\(3ab/(a-b)\\)"}, {"key": "D", "text": "\\((3a+b)/(a+b)\\)"}, {"key": "E", "text": "\\(-3ab/(a+b)\\)"}], "type": "mcq", "correct": "A", "explanation": "The slope is (3a−3b)/(a²−b²)=3/(a+b). Nonverticality ensures a+b≠0. Substituting (a²,3a) into y=mx+c gives c=3a−3a²/(a+b)=3ab/(a+b). This is the general expression in A.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Added nonverticality, which supplies the missing a+b≠0 restriction. Answer asks for the general expression, not a special parameter coincidence.", "source_document": "EST II - Math Level 2 - May 2021.pdf", "source_page": 13}, {"id": "est2-papers-2026-09-26:l2may:q47", "old_status": "needs_source_repair", "status": "ready", "question_id": "0f3e0356-c659-54d2-a982-45ec57e1a515", "stem": "A normally distributed test score has mean 100 and standard deviation 16. What fraction of the population scores below 100?", "choices": [{"key": "A", "text": "0.55"}, {"key": "B", "text": "0.84"}, {"key": "C", "text": "0.50"}, {"key": "D", "text": "0.98"}, {"key": "E", "text": "0.70"}], "type": "mcq", "correct": "C", "explanation": "A normal distribution is symmetric about its mean, with half its probability on each side. Equivalently z=(100−100)/16=0, whose cumulative probability is 0.50. The corresponding percentile is the 50th.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Added the normal-distribution assumption and expressed the answer as a fraction to match the printed options.", "source_document": "EST II - Math Level 2 - May 2021.pdf", "source_page": 17}, {"id": "est2-papers-2026-09-26:l2oct:q03", "old_status": "needs_source_repair", "status": "ready", "question_id": "435a674f-a11f-544c-a740-04115f2b4810", "stem": "Let \\(f(x)=-3\\cos(x^\\circ)\\), \\(g(x)=3\\sqrt7\\), and \\(h(x)=x^2-3\\). What is \\(f((h\\circ g)(2))\\)?", "choices": [{"key": "A", "text": "−2.99"}, {"key": "B", "text": "−1.5"}, {"key": "C", "text": "1"}, {"key": "D", "text": "5.94"}, {"key": "E", "text": "7.93"}], "type": "mcq", "correct": "B", "explanation": "First g(2)=3√7. Next h(3√7)=(3√7)²−3=63−3=60. Finally f(60)=−3cos60°=−3/2=−1.5. The angle unit is explicitly degrees.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Specified degrees, the missing convention required by the source answer choices.", "source_document": "EST II - Math Level 2 - October 2020.pdf", "source_page": 3}, {"id": "est2-papers-2026-09-26:l2oct:q22", "old_status": "needs_source_repair", "status": "ready", "question_id": "030fc279-24b3-570c-b6f9-11997fb78d8b", "stem": "Mr. Hernandez has 8 distinct greeting cards and 5 distinct friends. He sends exactly one card to each friend, using each card at most once. How many different assignments of cards to friends are possible?", "choices": [{"key": "A", "text": "6720"}, {"key": "B", "text": "3136"}, {"key": "C", "text": "112"}, {"key": "D", "text": "56"}, {"key": "E", "text": "40"}], "type": "mcq", "correct": "A", "explanation": "Choose the first friend’s card in 8 ways, the second’s in 7, then 6, 5, and 4 ways for the remaining friends. The product is 8×7×6×5×4=6720. This is P(8,5), because both cards and recipients are distinct.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Specified distinct cards and one card per friend, resolving the source’s ambiguous distribution rule.", "source_document": "EST II - Math Level 2 - October 2020.pdf", "source_page": 7}, {"id": "est2-papers-2026-09-26:l2oct:q31", "old_status": "needs_source_repair", "status": "ready", "question_id": "c7bdeee7-9368-58cd-a5b4-8f9ac3a31302", "stem": "A population is 1,427,647,786 in 2018 and grows by 0.59% per year under an annual compound-growth model. What population does the model predict for 2021, rounded to the nearest person?", "choices": [{"key": "A", "text": "8,423,121"}, {"key": "B", "text": "1,436,070,908"}, {"key": "C", "text": "1,444,543,726"}, {"key": "D", "text": "1,452,917,152"}, {"key": "E", "text": "1,453,066,534"}], "type": "mcq", "correct": "E", "explanation": "The annual growth factor is 1+0.0059=1.0059. There are 2021−2018=3 years of growth, so the prediction is 1,427,647,786(1.0059)³≈1,453,066,534.279. Rounding gives 1,453,066,534.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected choice E’s arithmetic and explicitly stated compound growth and rounding. This is a mathematical model using the source data, not a claim about measured population.", "source_document": "EST II - Math Level 2 - October 2020.pdf", "source_page": 9}, {"id": "est2-papers-2026-09-26:sample4:q48", "old_status": "needs_source_repair", "status": "ready", "question_id": "a64c4aa9-b66a-5f7e-a866-65909450df34", "stem": "On each day, independently of the other days, Mariam draws one portrait with probability 0.34 and otherwise draws none. What is the probability that she draws at most two portraits in three days, to three decimal places?", "choices": [{"key": "A", "text": "0.944"}, {"key": "B", "text": "0.961"}, {"key": "C", "text": "0.970"}, {"key": "D", "text": "0.977"}, {"key": "E", "text": "0.984"}], "type": "mcq", "correct": "B", "explanation": "The complement of at most two portraits in three days is exactly three portraits. Independence gives P(three)=0.34³=0.039304. Thus P(at most two)=1−0.039304=0.960696, which rounds to 0.961.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Added the missing independence assumption.", "source_document": "EST 2 Math Level 1 - Test Sample 4.pdf", "source_page": 13}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
